'use strict';
var uuidBase62 = require('uuid-base62/uuid-base62');

const alphabetics = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
const alphanumerics ="0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
const keyLength = 24;

exports.newKey = function () {
    // ensure that the string starts with a random alphabetic char
    let retval = alphabetic() + alphanumeric() + uuidBase62.v4();
    // occasionally, the base62 may be shorter, so pad if needed
    while (retval.length < keyLength) {
        retval += alphanumeric();
    } 
    return retval;
}

function alphabetic() {
    return alphabetics[Math.floor(Math.random() * alphabetics.length)];
}

function alphanumeric() {
    return alphanumerics[Math.floor(Math.random() * alphanumerics.length)];
}

